// <code-repl> — a <code-editor> + a Run affordance + an output pane. Real in-sandbox
// eval: composition-as-source code, run where it can actually run.
//
//   • host.available("compile") → route ANY language through the Host compiler
//     lane (clang/rustc/zig/go/StarlingMonkey → wasm), in-sandbox. Endpoint
//     contract: POST /run { language, source } → { ok, output }. Mirrors how
//     <document-cell> routes compute through `this.host` and degrades cleanly.
//   • STANDALONE (no runtime) → JS evals in a sandboxed Worker (never eval in the
//     page; see sandbox.js). Compiled languages show a clear, themed
//     "runtime needed for C/Rust/Zig/Go" state instead of pretending.
//
// Emits `work-run {language, ok, output}` after every run.
import { WbElement, html, css, define } from "../../core/element.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";
import { normalizeLang } from "./highlight.js";
import { runJs } from "./sandbox.js";
import "./work-editor.js";

const VARIANTS = defineVariants({
  variant: { options: ["card", "inline"], default: "card" },
});

// Languages the standalone floor can actually run (no compiler lane needed).
const STANDALONE_RUNNABLE = new Set(["js"]);
const COMPILED = { c: "C", cpp: "C", rust: "Rust", zig: "Zig", go: "Go" };

export class WorkRepl extends WbElement {
  static variants = VARIANTS;
  static props = [...variantAttrs(VARIANTS), "language", "gutter"];

  static properties = {
    ...WbElement.properties,
    _busy: { state: true },
    _result: { state: true },
    _live: { state: true },
  };

  static styles = css`
    :host { display: block; font-family: var(--work-font); }
    .shell { border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-surface); overflow: hidden; box-shadow: var(--work-shadow-sm); }
    :host([variant="inline"]) .shell { border: none; box-shadow: none; background: transparent; }

    .bar { display: flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-3); border-bottom: 1px solid var(--work-border);
      background: var(--work-surface-soft); }
    .lang { font-family: var(--work-font-mono); font-weight: 700; font-size: var(--work-text-sm);
      text-transform: uppercase; letter-spacing: 0.06em; color: var(--work-brand); }
    .where { font-family: var(--work-font-mono); font-size: var(--work-text-sm); color: var(--work-fg-subtle);
      display: inline-flex; align-items: center; gap: var(--work-space-1); }
    .where .dot { width: 7px; height: 7px; border-radius: var(--work-radius-pill);
      background: var(--work-warn); box-shadow: 0 0 0 var(--work-space-3px) var(--work-warn-glow); }
    .where[data-live="1"] .dot { background: var(--work-brand); box-shadow: 0 0 0 3px var(--work-brand-soft); }
    .run { margin-left: auto; font-family: var(--work-font); font-weight: 600; font-size: var(--work-text-sm);
      display: inline-flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-4); border-radius: var(--work-radius-sm);
      border: 1.5px solid transparent; background: var(--work-brand); color: var(--work-on-brand); cursor: pointer;
      transition: transform var(--work-dur) var(--work-ease), opacity var(--work-dur) var(--work-ease); }
    .run:hover { transform: translateY(-1px); }
    .run:active { transform: translateY(0); }
    .run:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); }
    .run[disabled] { opacity: 0.55; cursor: not-allowed; }
    .run .tri { width: 0; height: 0; border-left: 7px solid currentColor;
      border-top: 5px solid transparent; border-bottom: 5px solid transparent; }

    .out { border-top: 1px solid var(--work-border); background: var(--work-bg); }
    .out-head { padding: var(--work-space-2) var(--work-space-3); font-family: var(--work-font-mono);
      font-size: var(--work-text-sm); color: var(--work-fg-subtle); text-transform: uppercase;
      letter-spacing: 0.06em; border-bottom: 1px solid var(--work-border); display: flex; gap: var(--work-space-2); }
    .out-head .badge { margin-left: auto; text-transform: none; letter-spacing: 0; font-weight: 600; }
    .out-head .badge.ok { color: var(--work-ok); }
    .out-head .badge.err { color: var(--work-err); }
    pre.console { margin: 0; padding: var(--work-space-3); font-family: var(--work-font-mono);
      font-size: var(--work-text-sm); line-height: 1.6; color: var(--work-fg);
      white-space: pre-wrap; word-break: break-word; max-height: 280px; overflow: auto; }
    pre.console.err { color: var(--work-err); }
    .empty { color: var(--work-fg-subtle); font-style: italic; }

    .note { padding: var(--work-space-3); display: flex; gap: var(--work-space-3); align-items: flex-start;
      background: var(--work-surface-soft); }
    .note .ic { flex: none; width: 22px; height: 22px; border-radius: var(--work-radius-pill);
      background: var(--work-warn-fill); color: var(--work-warn); display: grid; place-items: center;
      font-weight: 700; font-family: var(--work-font-mono); }
    .note .body { font-size: var(--work-text-sm); line-height: 1.5; color: var(--work-fg-muted); }
    .note .body b { color: var(--work-fg); }
    .note code { font-family: var(--work-font-mono); color: var(--work-fg); background: var(--work-bg);
      padding: var(--work-space-px) var(--work-space-5px); border-radius: var(--work-radius-sm); }
  `;

  constructor() {
    super();
    this._busy = false;
    this._result = null;
    this._live = false;
  }

  get language() { return normalizeLang(this.attr("language", "js")); }

  connectedCallback() {
    if (this._source == null) {
      this._source = this.attr("value") != null ? this.attr("value")
        : (this.textContent || "").replace(/^\n/, "").replace(/\s+$/, "");
    }
    super.connectedCallback();
  }

  // can this language run AT ALL in the current context?
  _runnable() {
    if (this.host.available("compile")) return true;
    return STANDALONE_RUNNABLE.has(this.language);
  }

  async _run() {
    if (this._busy || !this._runnable()) return;
    const language = this.language;
    const source = this._editorValue();
    this._busy = true;
    let res;
    try {
      if (this.host.available("compile")) {
        // compiler lane: language → compile + run in-sandbox, server-side.
        const r = await this.host.request("/run", { body: { language, source } });
        res = { ok: !!(r && r.ok), output: (r && (r.output ?? r.stdout)) || "" };
        this._live = true;
      } else {
        res = await runJs(source);
        this._live = false;
      }
    } catch (e) {
      res = { ok: false, output: "run failed: " + (e.message || e) };
    }
    this._busy = false;
    this._result = res;
    this.dispatchEvent(new CustomEvent("work-run", {
      detail: { language, ok: res.ok, output: res.output },
      bubbles: true, composed: true,
    }));
  }

  _editorValue() {
    const ed = this.shadowRoot.querySelector("code-editor");
    return ed ? ed.value : this._source;
  }

  _onCodeChange(e) { this._source = e.detail.value; }

  _renderOut() {
    const language = this.language;
    const compiled = COMPILED[language];
    const canRun = this._runnable();

    // graceful "needs runtime" state for compiled languages standalone
    if (!canRun && compiled) {
      return html`
        <div class="note">
          <span class="ic">!</span>
          <div class="body">
            <b>${compiled} needs the runtime.</b> Standalone, this editor runs
            JavaScript in a sandbox. Compiling and running ${compiled} (and Rust /
            Zig / Go) routes through the Workbooks compiler lane — connect a runtime
            (<code>host.available("compile")</code>) and the same code runs in-sandbox, no setup.
          </div>
        </div>`;
    }

    const r = this._result;
    const badge = this._busy ? "" : r
      ? html`<span class="badge ${r.ok ? "ok" : "err"}">${r.ok ? "ok" : "error"}</span>`
      : "";
    let body;
    if (this._busy) body = html`<pre class="console"><span class="empty">running…</span></pre>`;
    else if (!r) body = html`<pre class="console"><span class="empty">output appears here — press Run</span></pre>`;
    else body = html`<pre class="console${r.ok ? "" : " err"}">${r.output ? r.output : html`<span class="empty">(no output)</span>`}</pre>`;

    return html`
      <div class="out">
        <div class="out-head"><span>output</span>${badge}</div>
        ${body}
      </div>`;
  }

  render() {
    const language = this.language;
    const canRun = this._runnable();
    const live = this.host.available("compile");
    const where = live ? "compiler lane" : (canRun ? "sandbox (worker)" : "needs runtime");
    const gutter = this.attr("gutter");
    return html`
      <div class="shell">
        <div class="bar">
          <span class="lang">${language}</span>
          <span class="where" data-live=${live ? 1 : 0}><span class="dot"></span>${where}</span>
          <button class="run" type="button" ?disabled=${!canRun} @click=${() => this._run()}>
            <span class="tri"></span>${this._busy ? "running" : "Run"}
          </button>
        </div>
        <code-editor language=${language} gutter=${gutter ?? ""} variant="inline"
          @work-code-change=${(e) => this._onCodeChange(e)}>${this._source || ""}</code-editor>
        ${this._renderOut()}
      </div>`;
  }
}

define("code-repl", WorkRepl);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// code · the POWERED tier — CodeMirror 6 behind the <code-editor> floor.
//
// The floor (work-editor.js) is a zero-dependency editing surface: a transparent
// <textarea> over a token-highlighted <pre> overlay, themed entirely from --work-*.
// This module is the powered alternative: a real CodeMirror 6 EditorView mounted in
// the element's SHADOW root, wired to the SAME public API — `getValue`/`setValue`,
// the `value`/`language`/`readonly` props, and the `work-code-change` event. Only
// the editing surface changes, never the contract; everything consuming
// <code-editor> (incl. <code-repl>) inherits the upgrade unchanged.
//
// Lazy-loaded from a CDN ESM at runtime (mirrors plot-tier / sqlite-wasm / wavelet):
// nothing is bundled, no dep is installed. `loadCodeMirror()` is a single-flight
// import() that resolves to the CM namespaces we need (view/state/commands + a
// language pack), overridable via `window.__WB_CODEMIRROR__` (tests / offline hosts
// inject their own). If the import fails (network-blocked, the gate's wasm/floor
// proof), the caller silently falls back to the floor textarea+highlight.
//
// THEMING (gate-a, token-leak): CM ships its own default colors + injects its own
// styles. We never let a literal leak — every color/font CM paints is READ from the
// element's computed --work-* tokens (readEditorTokens) and fed into an
// EditorView.theme + a HighlightStyle. Flip the host theme, re-read, re-theme → the
// editor re-themes light/dark/signal exactly like the floor.
//
// SCOPE (gate-b): CM6 supports shadow-root hosting — we pass `root: shadowRoot` to
// the EditorView so CM injects its <style> into the SHADOW root (adopted by CM into
// the provided root), NOT document.head. Nothing global is polluted.

// CDN ESM endpoints. Each is a single-flight import; overridable wholesale via
// window.__WB_CODEMIRROR__ (a pre-resolved bundle the tests/offline hosts inject).
const CDN = {
  view:       "https://esm.sh/@codemirror/view@6",
  state:      "https://esm.sh/@codemirror/state@6",
  commands:   "https://esm.sh/@codemirror/commands@6",
  language:   "https://esm.sh/@codemirror/language@6",
  langJs:     "https://esm.sh/@codemirror/lang-javascript@6",
  langRust:   "https://esm.sh/@codemirror/lang-rust@6",
  langPython: "https://esm.sh/@codemirror/lang-python@6",
  langJson:   "https://esm.sh/@codemirror/lang-json@6",
  langCss:    "https://esm.sh/@codemirror/lang-css@6",
  langHtml:   "https://esm.sh/@codemirror/lang-html@6",
  lezerHl:    "https://esm.sh/@lezer/highlight@1",
};

let _cmPromise = null;

/**
 * Single-flight lazy import of the CodeMirror 6 bundle. Resolves to a namespace
 * object: { EditorView, EditorState, keymap, defaultKeymap, history, historyKeymap,
 * lineNumbers, HighlightStyle, syntaxHighlighting, tags, langFor }.
 * Overridable for tests / offline hosts via `window.__WB_CODEMIRROR__`.
 * Throws (rejects) when the chunk can't load — the caller falls back to the floor.
 */
export function loadCodeMirror() {
  const override = typeof window !== "undefined" && window.__WB_CODEMIRROR__;
  if (override) return Promise.resolve(override);
  if (!_cmPromise) {
    _cmPromise = (async () => {
      const [view, state, commands, language, lezerHl] = await Promise.all([
        import(/* @vite-ignore */ CDN.view),
        import(/* @vite-ignore */ CDN.state),
        import(/* @vite-ignore */ CDN.commands),
        import(/* @vite-ignore */ CDN.language),
        import(/* @vite-ignore */ CDN.lezerHl),
      ]);
      // language packs load on demand by tag — only what the editor asks for.
      const langFor = makeLangLoader();
      return {
        EditorView: view.EditorView,
        keymap: view.keymap,
        lineNumbers: view.lineNumbers,
        EditorState: state.EditorState,
        Compartment: state.Compartment,
        defaultKeymap: commands.defaultKeymap,
        history: commands.history,
        historyKeymap: commands.historyKeymap,
        indentWithTab: commands.indentWithTab,
        HighlightStyle: language.HighlightStyle,
        syntaxHighlighting: language.syntaxHighlighting,
        indentUnit: language.indentUnit,
        tags: lezerHl.tags,
        langFor,
      };
    })().catch((e) => {
      _cmPromise = null; // allow a later retry
      throw e;
    });
  }
  return _cmPromise;
}

// Map a normalized code-editor language → a single-flight CM language extension
// loader. Unknown / plain languages resolve to `null` (no language extension —
// CM still edits text, just without grammar highlighting).
function makeLangLoader() {
  const cache = new Map();
  const defs = {
    js: () => import(/* @vite-ignore */ CDN.langJs).then((m) => m.javascript({ jsx: true, typescript: true })),
    ts: () => import(/* @vite-ignore */ CDN.langJs).then((m) => m.javascript({ jsx: true, typescript: true })),
    rust: () => import(/* @vite-ignore */ CDN.langRust).then((m) => m.rust()),
    python: () => import(/* @vite-ignore */ CDN.langPython).then((m) => m.python()),
    py: () => import(/* @vite-ignore */ CDN.langPython).then((m) => m.python()),
    json: () => import(/* @vite-ignore */ CDN.langJson).then((m) => m.json()),
    css: () => import(/* @vite-ignore */ CDN.langCss).then((m) => m.css()),
    html: () => import(/* @vite-ignore */ CDN.langHtml).then((m) => m.html()),
  };
  return (lang) => {
    const def = defs[lang];
    if (!def) return Promise.resolve(null);
    if (!cache.has(lang)) cache.set(lang, def().catch(() => null));
    return cache.get(lang);
  };
}

// Read the resolved --work-* token VALUES off the element (computed style). CM gets
// concrete colors/fonts, never `var(--work-*)` strings (CM writes them into its own
// generated stylesheet, where the var() context can differ). Reading the computed
// value locks CM's paint to the active theme — flip the theme, re-read, re-apply →
// the editor re-themes (the flip-delta gate passes). Syntax colors mirror the
// floor's `.tok-*` classes exactly (brand=keyword, ok=string, warn=number,
// fg-subtle=comment) so floor↔CM is the same palette.
export function readEditorTokens(el) {
  const cs = getComputedStyle(el);
  const v = (name, fallback) => (cs.getPropertyValue(name).trim() || fallback);
  return {
    fg:         v("--work-fg", "#121316"),
    fgSubtle:   v("--work-fg-subtle", "rgba(18,19,22,0.38)"),
    bg:         v("--work-bg", "#ffffff"),
    surfaceSoft: v("--work-surface-soft", "#f4f4f3"),
    border:     v("--work-border", "rgba(18,19,22,0.13)"),
    selection:  v("--work-brand-soft", "rgba(19,217,67,0.18)"),
    ring:       v("--work-ring", "rgba(19,217,67,0.4)"),
    caret:      v("--work-fg", "#121316"),
    fontMono:   v("--work-font-mono", "ui-monospace, monospace"),
    textSm:     v("--work-text-sm", "12.5px"),
    // syntax — the SAME token roles the floor highlighter uses
    kw:      v("--work-brand", "#13d943"),
    str:     v("--work-ok", "#0fae38"),
    num:     v("--work-warn", "#b8861b"),
    comment: v("--work-fg-subtle", "rgba(18,19,22,0.38)"),
  };
}

/**
 * Build the CM extensions that paint the editor entirely from `tk`
 * (readEditorTokens). Returns an array of extensions: an EditorView.theme (chrome:
 * bg/fg/gutter/selection/caret/focus-ring) + a token-driven syntaxHighlighting.
 */
export function buildTheme(CM, tk) {
  const theme = CM.EditorView.theme(
    {
      "&": {
        color: tk.fg,
        backgroundColor: "transparent",
        fontFamily: tk.fontMono,
        fontSize: tk.textSm,
      },
      ".cm-content": { caretColor: tk.caret, padding: "12px 0" },
      ".cm-line": { padding: "0 12px" },
      "&.cm-focused": { outline: "none" },
      "&.cm-focused .cm-cursor": { borderLeftColor: tk.caret },
      ".cm-cursor": { borderLeftColor: tk.caret },
      "&.cm-focused .cm-selectionBackground, .cm-selectionBackground, ::selection": {
        backgroundColor: tk.selection,
      },
      ".cm-gutters": {
        backgroundColor: tk.surfaceSoft,
        color: tk.fgSubtle,
        borderRight: "1px solid " + tk.border,
        fontVariantNumeric: "tabular-nums",
      },
      ".cm-activeLineGutter": { backgroundColor: "transparent" },
      ".cm-activeLine": { backgroundColor: "transparent" },
      ".cm-foldPlaceholder": { backgroundColor: "transparent", color: tk.fgSubtle },
      ".cm-scroller": { fontFamily: tk.fontMono, lineHeight: "1.6" },
    },
    { dark: false },
  );

  const hl = CM.HighlightStyle.define([
    { tag: CM.tags.keyword, color: tk.kw, fontWeight: "600" },
    { tag: [CM.tags.controlKeyword, CM.tags.moduleKeyword, CM.tags.definitionKeyword], color: tk.kw, fontWeight: "600" },
    { tag: [CM.tags.string, CM.tags.special(CM.tags.string)], color: tk.str },
    { tag: [CM.tags.number, CM.tags.bool, CM.tags.atom], color: tk.num },
    { tag: [CM.tags.comment, CM.tags.lineComment, CM.tags.blockComment], color: tk.comment, fontStyle: "italic" },
    { tag: [CM.tags.function(CM.tags.variableName), CM.tags.function(CM.tags.propertyName)], color: tk.fg },
    { tag: CM.tags.typeName, color: tk.fg },
  ]);

  return [theme, CM.syntaxHighlighting(hl)];
}

/**
 * Create + mount a CodeMirror EditorView in `parent` (the element's shadow root,
 * or a host node inside it). Wires the doc to `opts.doc`, sets language/readonly,
 * paints from `opts.tk`, and calls `opts.onChange(value)` on every doc edit.
 *
 * Returns { view, setDoc, setLanguage, setReadonly, setTheme, destroy } — the
 * imperative surface code-editor's getValue/setValue/_mountSurface drive. Language
 * + readonly + theme each live in a Compartment so they reconfigure without losing
 * the doc/selection/history (theme re-applies on every host theme flip).
 *
 * @param CM    the loaded CodeMirror namespace (loadCodeMirror())
 * @param parent  ShadowRoot (root for CM's injected styles) or an element in it
 * @param opts  { doc, language, readonly, tk, onChange, root }
 */
export function createEditorView(CM, parent, opts) {
  const langComp = new CM.Compartment();
  const roComp = new CM.Compartment();
  const themeComp = new CM.Compartment();
  const root = opts.root || parent.getRootNode();

  const updateListener = CM.EditorView.updateListener.of((vu) => {
    if (vu.docChanged && typeof opts.onChange === "function") {
      opts.onChange(vu.state.doc.toString());
    }
  });

  const baseExtensions = [
    CM.lineNumbers(),
    CM.history(),
    CM.keymap.of([...CM.defaultKeymap, ...CM.historyKeymap, CM.indentWithTab]),
    CM.indentUnit.of("  "),
    CM.EditorState.tabSize.of(2),
    CM.EditorView.lineWrapping,
    langComp.of([]),
    roComp.of([
      CM.EditorState.readOnly.of(!!opts.readonly),
      CM.EditorView.editable.of(!opts.readonly),
    ]),
    themeComp.of(buildTheme(CM, opts.tk)),
    updateListener,
  ];

  const state = CM.EditorState.create({
    doc: opts.doc || "",
    extensions: baseExtensions,
  });

  const view = new CM.EditorView({
    state,
    parent,
    // CM6 honors a `root` so its dynamically-injected styles land in the shadow
    // root's adopted stylesheet, not document.head (scope gate).
    root,
  });

  // load + apply the language grammar asynchronously (no language = plain text)
  const applyLanguage = (lang) => {
    CM.langFor(lang).then((ext) => {
      if (!view.dom.isConnected && !parent.contains(view.dom)) return;
      view.dispatch({ effects: langComp.reconfigure(ext ? [ext] : []) });
    });
  };
  applyLanguage(opts.language);

  return {
    view,
    setDoc(text) {
      const cur = view.state.doc.toString();
      if (cur === text) return;
      // selection clamps automatically. code-editor decides whether to re-emit
      // work-code-change (its own `silent` flag) — the updateListener always fires.
      view.dispatch({
        changes: { from: 0, to: view.state.doc.length, insert: text },
      });
    },
    getDoc() { return view.state.doc.toString(); },
    setLanguage(lang) { applyLanguage(lang); },
    setReadonly(ro) {
      view.dispatch({
        effects: roComp.reconfigure([
          CM.EditorState.readOnly.of(!!ro),
          CM.EditorView.editable.of(!ro),
        ]),
      });
    },
    setTheme(tk) {
      view.dispatch({ effects: themeComp.reconfigure(buildTheme(CM, tk)) });
    },
    destroy() { view.destroy(); },
  };
}

// Token-only syntax highlight — the zero-dep FLOOR for <wb-editor>.
//
// Deliberately minimal: a lightweight tokenizer that wraps comments, strings,
// numbers, and a per-language keyword set in <span class="tok-*"> spans styled
// from --work-* tokens. It is NOT a parser and makes no correctness claims — it is
// the readable floor. The powered tier swaps in CodeMirror behind the same
// <wb-editor> public API (see editor seam in wb-editor.js); this module is then
// simply not used. Output is HTML-escaped first, so it is safe to set as innerHTML.

const KEYWORDS = {
  js: ["const", "let", "var", "function", "return", "if", "else", "for", "while", "do",
    "switch", "case", "break", "continue", "new", "class", "extends", "super", "this",
    "import", "export", "from", "default", "async", "await", "yield", "try", "catch",
    "finally", "throw", "typeof", "instanceof", "in", "of", "delete", "void", "null",
    "undefined", "true", "false", "static", "get", "set"],
  c: ["int", "char", "float", "double", "void", "long", "short", "unsigned", "signed",
    "struct", "union", "enum", "typedef", "const", "static", "extern", "return", "if",
    "else", "for", "while", "do", "switch", "case", "break", "continue", "sizeof",
    "include", "define", "ifdef", "ifndef", "endif", "goto", "default"],
  rust: ["fn", "let", "mut", "const", "static", "struct", "enum", "trait", "impl",
    "pub", "use", "mod", "match", "if", "else", "for", "while", "loop", "return",
    "break", "continue", "self", "Self", "as", "ref", "move", "async", "await",
    "dyn", "where", "type", "unsafe", "true", "false"],
  zig: ["const", "var", "fn", "pub", "return", "if", "else", "for", "while", "switch",
    "struct", "enum", "union", "comptime", "try", "catch", "defer", "errdefer",
    "test", "import", "export", "extern", "inline", "true", "false", "null", "undefined"],
  go: ["package", "import", "func", "var", "const", "type", "struct", "interface",
    "map", "chan", "go", "defer", "return", "if", "else", "for", "range", "switch",
    "case", "default", "select", "break", "continue", "nil", "true", "false"],
};

// Languages that share C-ish comment/string syntax cover everything we tokenize.
const ALIASES = { javascript: "js", typescript: "js", ts: "js", golang: "go", "c++": "c", cpp: "c", h: "c" };

export function normalizeLang(lang) {
  const l = (lang || "js").toLowerCase();
  return ALIASES[l] || l;
}

export function escapeHtml(s) {
  return String(s).replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
}

// Tokenize one already-escaped line. We scan char-by-char so spans never nest or
// cross HTML-escape boundaries. Strings/comments win over keywords/numbers.
export function highlightLine(rawLine, lang) {
  const kw = new Set(KEYWORDS[normalizeLang(lang)] || KEYWORDS.js);
  const src = rawLine;
  let out = "";
  let i = 0;
  const n = src.length;

  const wrap = (cls, text) => `<span class="tok-${cls}">${escapeHtml(text)}</span>`;

  while (i < n) {
    const c = src[i];
    const rest = src.slice(i);

    // line comment  // ... or # ... (covers C preproc-ish + scripting)
    if (rest.startsWith("//") || c === "#") {
      out += wrap("comment", rest);
      break;
    }
    // block comment  /* ... */ (single-line slice only; multi-line handled by caller state)
    if (rest.startsWith("/*")) {
      const end = rest.indexOf("*/");
      const seg = end >= 0 ? rest.slice(0, end + 2) : rest;
      out += wrap("comment", seg);
      i += seg.length;
      continue;
    }
    // strings  " ' `
    if (c === '"' || c === "'" || c === "`") {
      let j = i + 1;
      while (j < n && src[j] !== c) { if (src[j] === "\\") j++; j++; }
      const seg = src.slice(i, Math.min(j + 1, n));
      out += wrap("str", seg);
      i = j + 1;
      continue;
    }
    // numbers
    if (/[0-9]/.test(c) && (i === 0 || /[^A-Za-z0-9_]/.test(src[i - 1]))) {
      const m = rest.match(/^0x[0-9a-fA-F]+|^[0-9]+\.?[0-9]*([eE][+-]?[0-9]+)?/);
      if (m) { out += wrap("num", m[0]); i += m[0].length; continue; }
    }
    // identifiers / keywords
    if (/[A-Za-z_]/.test(c)) {
      const m = rest.match(/^[A-Za-z_][A-Za-z0-9_]*/);
      const word = m[0];
      out += kw.has(word) ? wrap("kw", word) : escapeHtml(word);
      i += word.length;
      continue;
    }
    // everything else, escaped
    out += escapeHtml(c);
    i++;
  }
  return out;
}

// Highlight a whole document, line by line, tracking /* */ block-comment state
// across lines. Returns one HTML string with \n preserved (the overlay is a <pre>).
export function highlight(code, lang) {
  const lines = String(code).split("\n");
  let inBlock = false;
  const html = lines.map((line) => {
    if (inBlock) {
      const end = line.indexOf("*/");
      if (end < 0) return `<span class="tok-comment">${escapeHtml(line)}</span>`;
      const seg = line.slice(0, end + 2);
      inBlock = false;
      return `<span class="tok-comment">${escapeHtml(seg)}</span>` + highlightLine(line.slice(end + 2), lang);
    }
    // open an unterminated block comment?
    const open = line.lastIndexOf("/*");
    const close = line.lastIndexOf("*/");
    if (open >= 0 && close < open) {
      inBlock = true;
      return highlightLine(line.slice(0, open), lang) + `<span class="tok-comment">${escapeHtml(line.slice(open))}</span>`;
    }
    return highlightLine(line, lang);
  });
  return html.join("\n");
}

// Standalone JS evaluation, sandboxed — NEVER eval in the host page.
//
// We run the snippet inside a Web Worker created from a Blob URL. The worker has
// no DOM, no parent window, no access to the page's globals; `console.*` and the
// return value are streamed back as messages and rendered in the output pane. A
// wall-clock timeout terminates runaway code. This is the zero-runtime floor for
// the `js` language; compiled languages (C/Rust/Zig/Go) route through the Host
// compiler lane instead (see wb-repl.js).
//
// (A worker is still same-origin; for fully-untrusted third-party code the next
// rung is a sandboxed cross-origin <iframe>. The public API here — runJs() →
// {ok, output, value} — is identical either way, so the surface can harden
// without changing callers.)

const WORKER_SRC = `
  self.onmessage = (e) => {
    const code = e.data.code;
    const logs = [];
    const fmt = (a) => {
      try {
        if (typeof a === "string") return a;
        if (a instanceof Error) return a.name + ": " + a.message;
        return JSON.stringify(a, (k, v) => typeof v === "bigint" ? v.toString() + "n" : v, 2);
      } catch (_) { return String(a); }
    };
    const line = (level, args) => logs.push({ level, text: args.map(fmt).join(" ") });
    const console = {
      log: (...a) => line("log", a),
      info: (...a) => line("info", a),
      warn: (...a) => line("warn", a),
      error: (...a) => line("error", a),
      debug: (...a) => line("debug", a),
    };
    let ok = true, value;
    try {
      // strict-mode function scope; no access to self/postMessage from user code
      const fn = new Function("console", '"use strict";\\n' + code);
      value = fn(console);
    } catch (err) {
      ok = false;
      logs.push({ level: "error", text: (err && err.name ? err.name + ": " + err.message : String(err)) });
    }
    const done = (v) => self.postMessage({ ok, logs, value: v === undefined ? undefined : fmt(v) });
    // resolve a returned promise so async snippets show their result
    if (value && typeof value.then === "function") {
      value.then((v) => done(v), (err) => { logs.push({ level: "error", text: String(err && err.message || err) }); self.postMessage({ ok: false, logs, value: undefined }); });
    } else {
      done(value);
    }
  };
`;

/**
 * Run a JS snippet in a fresh sandboxed worker.
 * @returns {Promise<{ok:boolean, output:string, value?:string}>}
 */
export function runJs(code, { timeoutMs = 4000 } = {}) {
  return new Promise((resolve) => {
    let url, worker, timer;
    const cleanup = () => {
      clearTimeout(timer);
      if (worker) worker.terminate();
      if (url) URL.revokeObjectURL(url);
    };
    const finish = (res) => { cleanup(); resolve(res); };

    try {
      url = URL.createObjectURL(new Blob([WORKER_SRC], { type: "text/javascript" }));
      worker = new Worker(url);
    } catch (e) {
      return finish({ ok: false, output: "sandbox unavailable: " + (e.message || e) });
    }

    timer = setTimeout(() => {
      finish({ ok: false, output: "execution timed out (" + timeoutMs + "ms) — terminated runaway code." });
    }, timeoutMs);

    worker.onmessage = (e) => {
      const { ok, logs, value } = e.data || {};
      const parts = (logs || []).map((l) => l.text);
      if (value !== undefined) parts.push("⇒ " + value);
      finish({ ok: !!ok, output: parts.join("\n"), value });
    };
    worker.onerror = (e) => finish({ ok: false, output: "worker error: " + (e.message || "unknown") });

    worker.postMessage({ code });
  });
}

// <code-editor> — a themed code editor. The editing surface is the zero-dep FLOOR:
// a transparent <textarea> over a token-highlighted <pre> overlay, with a line-
// number gutter. Composition-as-source: the code IS the artifact's source, edited
// in place — emits `work-code-change {value}` on every edit.
//
// THE EDITOR-SWAP SEAM (now wired to CodeMirror 6):
//   The public API — the `value` property/attr, the `language`/`readonly` attrs, the
//   `work-code-change` event, and the `<code-editor>` tag — is the contract. The
//   editing surface itself is built by `_mountSurface()` / read+written via
//   `getValue()` / `setValue()`. The POWERED build (./codemirror-tier.js) overrides
//   ONLY those internals (mount a CodeMirror EditorView in the shadow root, read/
//   write its doc) behind the same public API; nothing that consumes <code-editor>
//   — including <code-repl> — changes. The floor is the lower rung of one ladder.
//
//   Tier resolution (mirrors chart-view): `engine="codemirror"|"floor"` attr or
//   `window.__WB_EDITOR_ENGINE__` force it; default "auto" prefers CodeMirror and
//   falls back to the floor INSTANTLY if the lazy CDN import fails (offline /
//   network-blocked / the gate's wasm proof). NO build step, pure ESM; CM is
//   lazy-loaded from a CDN (overridable via window.__WB_CODEMIRROR__), never bundled.
//
// Lit base: the surface chrome (gutter/overlay/textarea) is a Lit template. The
// highlighted overlay is trusted, already-escaped HTML (see highlight.js), bound
// with Lit's `unsafeHTML` directive — the escaping lives in the tokenizer, not the
// markup author. The textarea value is managed imperatively (a `ref`) so a re-render
// never disturbs the caret; Lit only re-renders the overlay/gutter via reactive
// state.
import { WbElement, html, css, define } from "../../core/element.js";
import { ref, createRef } from "lit/directives/ref.js";
import { unsafeHTML } from "lit/directives/unsafe-html.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";
import { highlight, normalizeLang } from "./highlight.js";
import { loadCodeMirror, readEditorTokens, createEditorView } from "./codemirror-tier.js";

const VARIANTS = defineVariants({
  variant: { options: ["card", "inline"], default: "card" },
});

export class WorkEditor extends WbElement {
  static variants = VARIANTS;
  // language + readonly reflected so :host([...]) + re-render react; gutter toggles linenos.
  // `engine` = tier override (auto | codemirror | floor).
  static props = [...variantAttrs(VARIANTS), "language", "readonly", "gutter", "placeholder", "engine"];

  static properties = {
    ...WbElement.properties,
    // the highlighted overlay markup + the gutter line list — reactive state
    _highlighted: { state: true },
    _lines: { state: true },
    // which tier rendered: "floor" | "codemirror" — toggles the floor wrap vs CM host
    _tier: { state: true },
  };

  static styles = css`
    :host { display: block; font-family: var(--work-font-mono); }
    .wrap { position: relative; display: flex;
      border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-bg); box-shadow: var(--work-shadow-sm); overflow: hidden; }
    :host([variant="inline"]) .wrap { border: none; box-shadow: none; background: var(--work-surface-soft); }

    .gutter { flex: none; padding: var(--work-space-3) var(--work-space-2);
      text-align: right; user-select: none; color: var(--work-fg-subtle);
      font-size: var(--work-text-sm); line-height: 1.6;
      background: var(--work-surface-soft); border-right: 1px solid var(--work-border);
      font-variant-numeric: tabular-nums; min-width: 2.2em; }
    :host([gutter="off"]) .gutter { display: none; }

    /* the surface: textarea and overlay are layered, pixel-identical metrics */
    .surface { position: relative; flex: 1 1 auto; min-width: 0; }
    .overlay, textarea {
      margin: 0; padding: var(--work-space-3);
      font-family: var(--work-font-mono); font-size: var(--work-text-sm);
      line-height: 1.6; tab-size: 2; white-space: pre; overflow-wrap: normal;
      letter-spacing: 0; word-spacing: 0; border: 0; box-sizing: border-box;
    }
    .overlay { position: absolute; inset: 0; pointer-events: none; color: var(--work-fg);
      overflow: auto; }
    textarea {
      position: relative; width: 100%; height: 100%; min-height: var(--_minh, 8.6em);
      display: block; resize: vertical; background: transparent;
      color: transparent; caret-color: var(--work-fg);
      outline: none; overflow: auto; }
    textarea::selection { background: var(--work-brand-soft); color: var(--work-fg); }
    textarea::placeholder { color: var(--work-fg-subtle); }
    :host([readonly]) textarea { caret-color: transparent; }

    /* token classes — styled ONLY from --work-* */
    .tok-kw { color: var(--work-brand); font-weight: 600; }
    .tok-str { color: var(--work-ok); }
    .tok-num { color: var(--work-warn); }
    .tok-comment { color: var(--work-fg-subtle); font-style: italic; }

    textarea:focus-visible ~ .overlay,
    .wrap:focus-within { box-shadow: none; }
    .wrap:focus-within { border-color: var(--work-brand); box-shadow: 0 0 0 3px var(--work-ring); }

    /* the POWERED surface: a CodeMirror EditorView mounts INTO .cm-host. The
       chrome (border/radius/bg/focus-ring) is the floor's — CM only owns the inner
       content/gutter, themed from --work-* via the tier's EditorView.theme. */
    .cm-host { display: none; }
    :host([data-tier="codemirror"]) .cm-host {
      display: block;
      border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-bg); box-shadow: var(--work-shadow-sm); overflow: hidden;
    }
    :host([variant="inline"][data-tier="codemirror"]) .cm-host {
      border: none; box-shadow: none; background: var(--work-surface-soft);
    }
    .cm-host:focus-within { border-color: var(--work-brand); box-shadow: 0 0 0 3px var(--work-ring); }
    /* when CM owns the surface, the floor wrap is removed from the box entirely */
    :host([data-tier="codemirror"]) .wrap { display: none; }
    .cm-host .cm-editor { min-height: var(--_minh, 8.6em); }
  `;

  constructor() {
    super();
    this._taRef = createRef();
    this._ovRef = createRef();
    this._cmRef = createRef();
    this._highlighted = "";
    this._lines = "";
    this._tier = "floor";   // until the CM lazy-load resolves (or auto picks floor)
    this._cm = null;        // the codemirror-tier handle when mounted
  }

  // ---- public API (the swap-stable contract) ---------------------------------

  get value() { return this.getValue(); }
  set value(v) { this.setValue(v == null ? "" : String(v)); }

  get language() { return normalizeLang(this.attr("language", "js")); }
  set language(v) { this.setAttribute("language", v); }

  // ---- editing-surface seam (floor impl; CodeMirror overrides these) ---------

  /** Read the current text. CM tier: from the EditorView doc. Floor: the textarea. */
  getValue() {
    if (this._cm) return this._cm.getDoc();
    const ta = this._taRef.value;
    return ta ? ta.value : (this._pending != null ? this._pending : "");
  }

  /** Write text + emit change. CM tier: into the EditorView doc. Floor: the textarea. */
  setValue(v, { silent = false } = {}) {
    if (this._cm) {
      if (this._cm.getDoc() === v) return;
      this._suppressEmit = silent;          // the CM updateListener fires; gate emit
      this._cm.setDoc(v);
      this._suppressEmit = false;
      if (!silent) { /* updateListener already emitted */ }
      return;
    }
    const ta = this._taRef.value;
    if (!ta) { this._pending = v; return; }
    if (ta.value === v) return;
    ta.value = v;
    this._paint();
    if (!silent) this._emitChange();
  }

  // ---- tier resolution (mirrors chart-view's _tierChoice) --------------------
  //   - attribute engine="floor" | "codemirror" forces it (the gate drives this)
  //   - window.__WB_EDITOR_ENGINE__ = "floor" | "codemirror" is the host opt-out
  //   - default "auto": prefer CodeMirror, fall back to the floor if it can't load.
  _tierChoice() {
    const attr = this.attr("engine");
    if (attr === "floor" || attr === "codemirror") return attr;
    const host = typeof window !== "undefined" && window.__WB_EDITOR_ENGINE__;
    if (host === "floor" || host === "codemirror") return host;
    return "auto";
  }

  /** Build the editing surface. Resolves the tier: the FLOOR is wired immediately
   *  (it never blocks on a CDN and is the guaranteed render); when the tier is
   *  codemirror/auto, the CM EditorView is lazy-loaded and, on success, takes over
   *  the surface behind the same getValue/setValue/event contract. */
  _mountSurface() {
    this._mountFloor();
    const choice = this._tierChoice();
    if (choice !== "floor") this._mountCodeMirror(choice === "codemirror");
  }

  // The POWERED tier — CodeMirror 6, lazy-loaded from a CDN. On success it mounts an
  // EditorView in .cm-host (shadow-scoped styles), seeds it with the floor's current
  // value, and flips _tier → "codemirror" (CSS hides the floor wrap). On failure
  // (network-blocked / load error) the floor stays — forced "codemirror" still
  // degrades gracefully; the floor IS the guaranteed render (the wasm gate proves it).
  _mountCodeMirror(forced) {
    loadCodeMirror().then((CM) => {
      const host = this._cmRef.value;
      if (!host || this._cm) return;
      const tk = readEditorTokens(this);
      this._cm = createEditorView(CM, host, {
        doc: this.getValue(),
        language: this.language,
        readonly: this.boolAttr("readonly"),
        tk,
        root: this.shadowRoot,
        onChange: () => { if (!this._suppressEmit) this._emitChange(); },
      });
      this._tier = "codemirror";
      this.setAttribute("data-tier", "codemirror");
    }).catch((e) => {
      if (forced) console.warn("code-editor: CodeMirror failed to load, keeping floor", e);
      // floor remains; nothing to do.
    });
  }

  _mountFloor() {
    const ta = this._taRef.value;
    if (!ta) return;
    const sync = () => { this._paint(); this._emitChange(); };
    ta.addEventListener("input", sync);
    ta.addEventListener("scroll", () => {
      const ov = this._ovRef.value;
      if (ov) { ov.scrollTop = ta.scrollTop; ov.scrollLeft = ta.scrollLeft; }
    });
    // soft tab on Tab (floor nicety; CM handles this natively later)
    ta.addEventListener("keydown", (e) => {
      if (e.key === "Tab" && !this.boolAttr("readonly")) {
        e.preventDefault();
        const s = ta.selectionStart, en = ta.selectionEnd;
        ta.value = ta.value.slice(0, s) + "  " + ta.value.slice(en);
        ta.selectionStart = ta.selectionEnd = s + 2;
        sync();
      }
    });
    // seed the textarea with the captured initial source, then paint the overlay
    if (ta.value === "" && this._initial) ta.value = this._initial;
    this._paint();
  }

  // ---- internals -------------------------------------------------------------

  // Recompute the highlight overlay + gutter into reactive state; Lit binds them
  // (overlay via unsafeHTML — the highlight HTML is escaped at the source).
  _paint() {
    const ta = this._taRef.value;
    if (!ta) return;
    const code = ta.value;
    // trailing newline keeps the overlay tall enough to match the textarea
    this._highlighted = highlight(code, this.language) + "\n";
    const n = code.split("\n").length;
    let g = "";
    for (let k = 1; k <= n; k++) g += k + "\n";
    this._lines = g;
  }

  _emitChange() {
    const value = this.getValue();
    this._pending = value;
    this.dispatchEvent(new CustomEvent("work-code-change", {
      detail: { value }, bubbles: true, composed: true,
    }));
  }

  connectedCallback() {
    // composition-as-source: capture slotted text ONCE before the base wipes it.
    if (this._initial == null) {
      this._initial = this.attr("value") != null ? this.attr("value") : (this.textContent || "");
      // strip a single leading newline authors get from writing the tag on its own line
      this._initial = this._initial.replace(/^\n/, "").replace(/\s+$/, "");
    }
    super.connectedCallback();
    // Re-theme the powered CM surface when the host flips data-work-theme — CM holds
    // computed token VALUES (not var()), so a flip must re-read + reconfigure. The
    // floor re-themes via the CSS cascade automatically; only CM needs the nudge.
    if (typeof MutationObserver !== "undefined") {
      this._themeObs = new MutationObserver(() => this._retheme());
      this._themeObs.observe(document.documentElement, { attributes: true, attributeFilter: ["data-work-theme"] });
    }
  }

  disconnectedCallback() {
    if (this._themeObs) { this._themeObs.disconnect(); this._themeObs = null; }
    if (this._cm) { this._cm.destroy(); this._cm = null; }
    super.disconnectedCallback();
  }

  _retheme() {
    if (this._cm) this._cm.setTheme(readEditorTokens(this));
  }

  // Lit lifecycle: wire the surface once the template + textarea exist.
  firstUpdated() {
    this._mountSurface();
  }

  // Propagate language/readonly to the CM tier on every (re)render. CM reconfigure
  // is idempotent — re-applying the same grammar/readonly is a no-op — so we sync
  // unconditionally rather than diffing the reactive-property map (language is a
  // prototype getter, so it never lands in Lit's `changed` set). The floor reads
  // these straight off attributes in _paint()/render() and needs no propagation.
  updated() {
    if (!this._cm) return;
    if (this._cmLang !== this.language) { this._cmLang = this.language; this._cm.setLanguage(this.language); }
    const ro = this.boolAttr("readonly");
    if (this._cmRo !== ro) { this._cmRo = ro; this._cm.setReadonly(ro); }
  }

  render() {
    const ro = this.boolAttr("readonly");
    const ph = this.attr("placeholder", "");
    return html`
      <div class="wrap">
        <pre class="gutter" aria-hidden="true">${this._lines}</pre>
        <div class="surface">
          <textarea ${ref(this._taRef)} spellcheck="false" autocomplete="off"
            autocapitalize="off" wrap="off" ?readonly=${ro}
            placeholder=${ph}></textarea>
          <pre class="overlay" aria-hidden="true" ${ref(this._ovRef)}>${unsafeHTML(this._highlighted)}</pre>
        </div>
      </div>
      <div class="cm-host" ${ref(this._cmRef)}></div>`;
  }
}

define("code-editor", WorkEditor);
